// ANTES: tres funciones de la app saben cómo guarda sus datos el tarifario
const tarifarioViejo = { baseKg: 120, zonas: { CABA: { recargo: 0 }, GBA1: { recargo: 450 } } };
const cotizarAcoplado = (t, zona, kg) => t.baseKg * kg + t.zonas[zona].recargo;
const facturarAcoplado = (t, zona, kg) => ({ neto: t.baseKg * kg + t.zonas[zona].recargo, zona });
