// BAJA COHESIÓN: una función con cuatro razones para cambiar
function cerrarRutaMezclada(ruta, enviar) {
  const entregadas = ruta.paradas.filter(p => p.estado === 'entregado');     // razón 1: qué cuenta como entregado
  const pago = 1500 + entregadas.length * 320;                               // razón 2: cómo se le paga al chofer
  const texto = `Ruta ${ruta.id}: ${entregadas.length}/${ruta.paradas.length} entregas, pago ${pago}`; // razón 3: redacción
  enviar('whatsapp', texto);                                                 // razón 4: por qué canal se avisa
  return pago;
}

// ALTA COHESIÓN: cada pieza tiene una sola razón para cambiar
const entregadasDe = ruta => ruta.paradas.filter(p => p.estado === 'entregado');
