const resumen = (ruta, n, pago) => `Ruta ${ruta.id}: ${n}/${ruta.paradas.length} entregas, pago ${pago}`;
function cerrarRuta(ruta, avisar) {
  const n = entregadasDe(ruta).length, pago = pagoChofer(n);
  avisar(resumen(ruta, n, pago));
  return pago;
}

