// Un proyecto chico de logística, descrito como «módulo: módulos que importa»
const proyecto = {
  pantallas: ['cotizador', 'rutas', 'tema'],
  cotizador: ['tarifario', 'mapas', 'tema'],
  rutas: ['mapas', 'avisos', 'tarifario'],
  tarifario: ['base'],
  mapas: ['base', 'rutas'],         // «mapas» importa a «rutas» y «rutas» importa a «mapas»
  avisos: ['base'],
  tema: [],
  base: [],
};
const nombres = Object.keys(proyecto);
const entran = Object.fromEntries(nombres.map(n => [n, nombres.filter(m => proyecto[m].includes(n))]));
console.log('módulo'.padEnd(11), 'salen', 'entran');
for (const n of nombres) console.log(n.padEnd(11), String(proyecto[n].length).padEnd(5), entran[n].length, entran[n].length ? '  <- ' + entran[n].join(', ') : '');

// ¿Hay ciclos? Buscamos, desde cada módulo, un camino que vuelva a él.
function ciclosDesde(inicio) {
  const hallados = [];
  (function ir(actual, camino) {
    for (const sig of proyecto[actual]) {
      if (sig === inicio) hallados.push([...camino, inicio].join(' -> '));
      else if (!camino.includes(sig)) ir(sig, [...camino, sig]);
    }
  })(inicio, [inicio]);
  return hallados;
}
const vistos = new Set();
for (const n of nombres) for (const c of ciclosDesde(n)) { const clave = c.split(' -> ').slice(0, -1).sort().join(); if (!vistos.has(clave)) { vistos.add(clave); console.log('ciclo:', c); } }

// Grafo de imports de un proyecto TypeScript, solo con la biblioteca estándar de Node.
// Uso: node grafo2.js <carpeta-src>
const fs = require('fs'), path = require('path');
const SRC = process.argv[2];
const files = [];
(function recorrer(d) { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) recorrer(p); else if (/\.(ts|tsx|js)$/.test(e.name) && !/\.d\.ts$/.test(e.name)) files.push(p); } })(SRC);
const nombre = p => path.relative(SRC, p).replace(/(\.web|\.native)?\.(tsx|ts|js)$/, '');
const modulos = new Set(files.map(nombre));
const estaticas = {}, otras = {};          // «estaticas»: se cargan al arrancar; «otras»: de tipos o perezosas
for (const m of modulos) { estaticas[m] = new Set(); otras[m] = new Set(); }
const RE = /(import\s+type\b[^'"`;]*?from\s*['"](\.[^'"]+)['"])|((?:import|export)\b[^'"`;]*?from\s*['"](\.[^'"]+)['"])|(require\(\s*['"](\.[^'"]+)['"]\s*\))|(import\(\s*['"](\.[^'"]+)['"]\s*\))/g;
for (const f of files) {
  const de = nombre(f), src = fs.readFileSync(f, 'utf8');
  for (const m of src.matchAll(RE)) {
    const spec = m[2] || m[4] || m[6] || m[8];
    let a = path.relative(SRC, path.normalize(path.join(path.dirname(f), spec)));
    if (!modulos.has(a) && modulos.has(a + '/index')) a += '/index';
    if (!modulos.has(a) || a === de) continue;
    // un import cuyos nombres son todos «type X» se borra al compilar: no cuenta como dependencia al arrancar
    const llaves = (m[3] || '').match(/\{([^}]*)\}/), soloTipos = llaves && llaves[1].split(',').filter(x => x.trim()).every(x => /^\s*type\s/.test(x));
    (m[4] && !soloTipos ? estaticas : otras)[de].add(a);
  }
}
const todas = {}; for (const m of modulos) todas[m] = new Set([...estaticas[m], ...otras[m]]);
const entrada = {}; for (const m of modulos) entrada[m] = new Set();
for (const m of modulos) for (const t of todas[m]) entrada[t].add(m);
const top = (g, n) => [...modulos].map(m => [m, g[m].size]).sort((x, y) => y[1] - x[1] || (x[0] < y[0] ? -1 : 1)).slice(0, n);
const aristas = [...modulos].reduce((s, m) => s + todas[m].size, 0);
console.log(`archivos: ${files.length}, módulos: ${modulos.size}, aristas: ${aristas}, promedio de salida: ${(aristas / modulos.size).toFixed(1)}`);
console.log('más importados (entrada):', top(entrada, 6).map(x => x.join(' ')).join(' | '));
console.log('más importan (salida):', top(todas, 6).map(x => x.join(' ')).join(' | '));
// Ciclos de cualquier tamaño: componentes fuertemente conexos (Tarjan) sobre los imports estáticos.
function ciclos(g) {
  let i = 0; const idx = {}, low = {}, pila = [], en = new Set(), res = [];
  function visitar(v) { idx[v] = low[v] = i++; pila.push(v); en.add(v);
    for (const w of g[v]) { if (!(w in idx)) { visitar(w); low[v] = Math.min(low[v], low[w]); } else if (en.has(w)) low[v] = Math.min(low[v], idx[w]); }
    if (low[v] === idx[v]) { const c = []; let w; do { w = pila.pop(); en.delete(w); c.push(w); } while (w !== v); if (c.length > 1) res.push(c); } }
  for (const v of modulos) if (!(v in idx)) visitar(v);
  return res;
}
const cTodas = ciclos(todas), cEst = ciclos(estaticas);
console.log(`ciclos (grupos de módulos que se importan entre sí): con todos los imports ${cTodas.length}, solo con imports estáticos ${cEst.length}`);
for (const c of cTodas) console.log('  grupo en ciclo:', c.length, 'módulos:', c.sort().join(', '));
for (const m of process.argv.slice(3)) console.log(`${m}: entran ${entrada[m].size}, salen ${todas[m].size}`);
